$paths = @("docs/ttqs-quality-20261016/quality-review/0075_R01/candidate/0075_R01_body.md","docs/ttqs-quality-20261016/quality-review/0075_R01/inputs/SYNTHETIC_REPLACEMENT_REGISTER_0075_R01.csv")
foreach($p in $paths){ Write-Output ($p + " => " + (Get-Item $p).Length + " bytes") }

